// Lightweight UI i18n for TCS Mail. Source UI strings remain pt-BR; en-US is
// applied at render time so legacy surfaces can be localized without a heavy
// runtime or duplicated templates.

import {RC8FIX1_EN} from './rc8fix1_en.js';
const STORAGE_KEY='tcs.uiLanguage';
const EFFECTIVE_KEY='tcs.effectiveLocale';
const SUPPORTED=new Set(['pt-BR','en-US']);
let preference='system';
let locale='pt-BR';
let observer=null;

export function normalizeLanguagePreference(value){
 const v=String(value||'system').trim();
 if(v==='system'||SUPPORTED.has(v))return v;
 const l=v.toLowerCase();
 if(l.startsWith('pt'))return'pt-BR';
 if(l.startsWith('en'))return'en-US';
 return'system';
}
export function systemLocale(){
 const langs=[...(navigator.languages||[]),navigator.language].filter(Boolean).map(x=>String(x).toLowerCase());
 return langs.some(x=>x.startsWith('pt'))?'pt-BR':'en-US';
}
export function resolveLocale(pref=preference){const p=normalizeLanguagePreference(pref);return p==='system'?systemLocale():p}
export function getLocale(){return locale}
export function getLanguagePreference(){return preference}
export function localeCode(){return locale}
export function isEnglish(){return locale==='en-US'}
export function initI18n(pref='system'){
 preference=normalizeLanguagePreference(pref||localStorage.getItem(STORAGE_KEY)||'system');
 locale=resolveLocale(preference);
 try{localStorage.setItem(STORAGE_KEY,preference);localStorage.setItem(EFFECTIVE_KEY,locale)}catch{}
 document.documentElement.lang=locale;
 translateDocument();
 return locale;
}
export function setLanguagePreference(pref){
 preference=normalizeLanguagePreference(pref);locale=resolveLocale(preference);
 try{localStorage.setItem(STORAGE_KEY,preference);localStorage.setItem(EFFECTIVE_KEY,locale)}catch{}
 document.documentElement.lang=locale;translateDocument();return locale;
}

