const PATTERNS=[
 [/^Mover (\d+) mensagem\(ns\) para (.+)\?$/i,(_,n,folder)=>`Move ${n} message(s) to ${folder}?`],
 [/^(\d+) mensagem\(ns\) movida\(s\)\.$/i,(_,n)=>`${n} message(s) moved.`],
 [/^(\d+) de (\d+) mensagem\(ns\) movida\(s\)\. As demais foram preservadas\.$/i,(_,ok,total)=>`${ok} of ${total} message(s) moved. The others were preserved.`],
 [/^Mover (\d+) mensagem\(ns\) para a Lixeira\?$/i,(_,n)=>`Move ${n} message(s) to Trash?`],
 [/^Excluir definitivamente (\d+) mensagem\(ns\)\? Esta ação não pode ser desfeita\.$/i,(_,n)=>`Permanently delete ${n} message(s)? This cannot be undone.`],
 [/^(\d+) mensagem\(ns\)$/i,(_,n)=>`${n} message(s)`],
 [/^(\d+) mensagem\(ns\) \.eml importada\(s\)\.$/i,(_,n)=>`${n} .eml message(s) imported.`],
 [/^(\d+) mensagem\(ns\) exportada\(s\)\.$/i,(_,n)=>`${n} message(s) exported.`],
 [/^(\d+) mensagem\(ns\) exportada\(s\) com conteúdo RFC822\.$/i,(_,n)=>`${n} message(s) exported with RFC822 content.`],
 [/^(\d+) mensagem\(ns\) importada\(s\) do Maildir\.$/i,(_,n)=>`${n} message(s) imported from Maildir.`],
 [/^(\d+) mensagem\(ns\) importada\(s\) do MBOX\.$/i,(_,n)=>`${n} message(s) imported from MBOX.`],
 [/^(\d+) mensagem\(ns\) excluída\(s\)\.(.*)$/i,(_,n,rest)=>`${n} message(s) deleted.${rest||''}`],
 [/^Mover (\d+) mensagem\(ns\)$/i,(_,n)=>`Move ${n} message(s)`],
 [/^Excluir definitivamente (\d+) mensagem\(ns\)\?$/i,(_,n)=>`Delete ${n} message(s) permanently?`],
 [/^Marcar (\d+) mensagem\(ns\) como Spam\?$/i,(_,n)=>`Mark ${n} message(s) as spam?`],
 [/^(\d+) ocorrência\(s\)$/i,(_,n)=>`${n} occurrence(s)`],
 [/^Conta (.+) conectada com segurança\. Iniciando sincronização…$/i,(_,mail)=>`Account ${mail} connected securely. Starting synchronization…`],
 [/^Conta (.+)$/i,(_,x)=>`Account ${x}`],
 [/^Conversa · (\d+) mensagens?$/i,(_,n)=>`Conversation · ${n} message${n==='1'?'':'s'}`],
 [/^Sempre carregar imagens remotas do domínio (.+)\?$/i,(_,d)=>`Always load remote images from domain ${d}?`],
 [/^Excluir a pasta (.+)\?$/i,(_,f)=>`Delete folder ${f}?`],
 [/^Provider (.+)$/i,(_,x)=>`Provider ${x}`],
 [/^Para (.+)$/i,(_,x)=>`To ${x}`],
 [/^De (.+)$/i,(_,x)=>`From ${x}`],
];

function preserveSpace(original,value){const a=original.match(/^\s*/)?.[0]||'',b=original.match(/\s*$/)?.[0]||'';return a+value+b}
Object.assign(EN, RC8FIX1_EN);
export function tr(value){
 const s=String(value??'');if(locale!=='en-US'||!s)return s;
 const trimmed=s.trim();if(!trimmed)return s;
 if(Object.prototype.hasOwnProperty.call(EN,trimmed))return preserveSpace(s,EN[trimmed]);
 for(const [re,fn] of PATTERNS){const m=trimmed.match(re);if(m)return preserveSpace(s,fn(...m))}
 // Restricted phrase replacements are useful for UI status lines that contain
 // dates/counts but are not user-authored message content.
 let out=trimmed;
 const parts=[
  [' mensagem(ns)',' message(s)'],[' mensagem(ns) ',' message(s) '],[' · Para ',' · To '],[' · última sync ',' · last sync '],
  ['Falha no diagnóstico:','Diagnostics failed:'],['Falha no runtime:','Runtime failed:'],['Falha no teste:','Test failed:'],
  ['Erro: ','Error: '],['Acompanhamento criado.','Follow-up created.'],['Nenhum ','No ']
 ];
 for(const [a,b] of parts)out=out.replace(a,b);
 return preserveSpace(s,out);
}
export const t=tr;

const SKIP_SELECTOR=[
 'input','textarea','[contenteditable="true"]','pre','code','iframe','.body','.snippet','.subject','.rawSource',
 '.recipientChip','.senderAvatar','.threadItem p','.threadMessageText','.readerHead h1','.readerMeta','.draftPreview h1','.attachmentActions > span','.aiSourceCard > div','.aiResult section p:not(.aiEmpty):not(.aiBusy):not(.error)','[data-i18n-skip]'
].join(',');
const ATTRS=['title','aria-label','placeholder'];
function shouldSkip(el){return !el||el.nodeType!==1||!!el.closest?.(SKIP_SELECTOR)}
function translateAttrs(el){if(locale!=='en-US'||shouldSkip(el))return;for(const a of ATTRS){if(el.hasAttribute?.(a)){const old=el.getAttribute(a),next=tr(old);if(next!==old)el.setAttribute(a,next)}}}
function translateTextNode(node){if(locale!=='en-US'||!node?.parentElement||shouldSkip(node.parentElement))return;const old=node.nodeValue||'',next=tr(old);if(next!==old)node.nodeValue=next}
export function translateDom(root=document.body){
 if(locale!=='en-US'||!root)return;
 if(root.nodeType===3){translateTextNode(root);return}
 if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11)return;
 if(root.nodeType===1)translateAttrs(root);
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT);
 let n;while((n=walker.nextNode())){if(n.nodeType===3)translateTextNode(n);else translateAttrs(n)}
}
export function translateDocument(){if(document?.body)translateDom(document.body);document.documentElement.lang=locale}
export function installI18nObserver(root=document.body){
 observer?.disconnect?.();if(!root)return null;
 observer=new MutationObserver(muts=>{if(locale!=='en-US')return;for(const m of muts){if(m.type==='characterData')translateTextNode(m.target);else if(m.type==='attributes')translateAttrs(m.target);else for(const n of m.addedNodes)translateDom(n)}});
 observer.observe(root,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:ATTRS});
 translateDom(root);return observer;
}
export function dateLocale(){return locale}
